from pathlib import Path
import make_extra_pages
from ratings import rating
import json, html, re

ROOT=Path(__file__).parent
OUT=ROOT/'dist'
esc=html.escape
P=json.loads((ROOT/'data/products-research.json').read_text())
C=json.loads((ROOT/'data/clinical-research.json').read_text())
S={x['id']:x for x in C['core_sources']}
S['SUP1']=C['supplementary_referral_source']
routes=[]
DATE='November 12, 2026'

def link(url,label,cls=''):
    return f'<a class="{cls}" href="{esc(url,quote=True)}">{label}</a>'
def btn(url,label,secondary=False):
    return link(url,label,'btn secondary' if secondary else 'btn')
def sources(*ids):
    return '<h2 id="sources">Sources behind this guide</h2><ol class="source-list">'+''.join(f'<li>{link(S[i]["url"],esc(S[i].get("organization",S[i].get("authors","Research")))+": "+esc(S[i]["title"]))}</li>' for i in ids)+'</ol><p class="note-small">Sources checked November 12, 2026. This is general information, not a diagnosis or an individualized treatment recommendation.</p>'
def callout(title,text,rose=False):
    return f'<div class="callout {"rose" if rose else ""}"><strong>{title}</strong><p>{text}</p></div>'
def disclosure():
    from commerce import disclosure as commerce_disclosure
    return commerce_disclosure()

def photo(name,alt,caption='Illustrative bathroom photography, not a product recommendation.'):
    return f'<figure class="article-figure"><img src="/assets/{name}.webp" alt="{alt}" loading="lazy"><figcaption>{caption} <a href="/our-method/#photography">Photo credits</a>.</figcaption></figure>'
def layout(path,title,description,content):
    from commerce import revise_page
    title,description,content = revise_page(path,title,description,content)
    from reader_copy import refine_page
    title,description,content = refine_page(path,title,description,content)
    from journey import refine as refine_journey
    title,description,content = refine_journey(path,title,description,content)
    nav=[('/body-odor/','Start here'),('/external-washes/','Body washes'),('/odor-and-menopause/','Intimate odor'),('/probiotics/','Probiotics')]
    navhtml=''.join(f'<a href="{u}" '+('aria-current="page"' if path==u else '')+f'>{t}</a>' for u,t in nav)
    brand='<span class="brand-mark" aria-hidden="true">m</span><span><span class="brand-name">menopause wash</span><span class="brand-sub">Body odor • Product comparisons</span></span>'
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{esc(title)} | Menopause Wash</title><meta name="description" content="{esc(description,quote=True)}"><meta name="theme-color" content="#422C3D"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="topbar">UNDERSTAND THE CHANGE · FIND WHAT MAY HELP</div><header class="header"><div class="wrap header-inner"><a href="/" class="brand" aria-label="Menopause Wash home">{brand}</a><button class="menu" aria-expanded="false" aria-controls="navigation">Menu</button><nav class="nav" id="navigation" aria-label="Main navigation">{navhtml}<a class="nav-cta" href="/external-washes/">Compare washes</a></nav></div></header><main id="main">{content}</main><footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="/">{brand}</a><p>Washes and body-care products discussed in menopause communities, with the sources and label details beside each option.</p><p>General information for adults. These guides have not been reviewed by a clinician.</p></div><div><h4>Find your next step</h4><a href="/odor-and-menopause/">Vaginal odor explained</a><a href="/gentle-care/">Gentle vulva care</a><a href="/external-washes/">Compare body washes</a><a href="/probiotics/">Explore probiotic evidence</a><a href="/when-to-get-checked/">Know when to get checked</a></div><div><h4>Behind the guides</h4><a href="/our-method/">How we research</a><a href="/sources/">Sources & research</a><a href="/affiliate-disclosure/">Affiliate disclosure</a><a href="/privacy/">Privacy</a><a href="/appointment-checklist/">Appointment checklist</a></div></div><div class="footer-base"><span>© 2026 Menopause Wash · Private editorial concept</span><span>Sources checked {DATE} · Affiliate links inactive</span></div></div></footer></body></html>'''
    def label_table(match):
        table=match.group(0)
        header=re.search(r'<thead>(.*?)</thead>',table,re.S)
        if not header:return table
        labels=re.findall(r'<th[^>]*>(.*?)</th>',header.group(1),re.S)
        def label_row(row):
            cells=re.findall(r'<td([^>]*)>(.*?)</td>',row.group(1),re.S)
            if not cells:return row.group(0)
            return '<tr>'+''.join(f'<td{attrs} data-label="{esc(re.sub("<[^>]*>","",labels[i]),quote=True)}">{value}</td>' for i,(attrs,value) in enumerate(cells))+'</tr>'
        return re.sub(r'<tr>(.*?)</tr>',label_row,table,flags=re.S)
    page=re.sub(r'<table>.*?</table>',label_table,page,flags=re.S)
    dest=OUT/(path.strip('/') or '.')/'index.html'
    dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(page.replace(chr(8212), ": "))
    routes.append({'path':path,'title':title,'description':description})

def article(path,title,dek,body,category='The care library'):
    content=f'''<div class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / {esc(category)}</div><header class="article-head"><span class="eyebrow">{category}</span><h1>{title}</h1><p class="dek">{dek}</p><p class="byline">Sources checked {DATE} · Not clinically reviewed</p></header><div class="article-layout"><article class="article-body">{body}</article><aside class="side-note"><span class="eyebrow">A useful reminder</span><h3>Your comfort comes first.</h3><p>You do not need a special wash to be clean. Start with gentle external care, and get a new or persistent change checked.</p><a href="/when-to-get-checked/">When to see a clinician</a><a href="/appointment-checklist/">Prepare for an appointment</a><a href="/our-method/">How we research our guides</a></aside></div></div>'''
    layout(path,title,dek,content)

